  function formSubmit() {
    $("#subscribe").submit((e) => {
      axios({
        method: "POST",
        url: "/.netlify/functions/pressReleaseSub",
        // data: fd,
        data: $("#subscribe").serialize(),
      })
        .then((response) => {
          // console.log(response); // Uncomment for debug
          $("#subscribe").hide();
          $("#thanks").show();
          setTimeout(() => {
            $("#subscribe").show();
            $("#thanks").hide();
          }, 5000);
          $("#subscribe")[0].reset();
          console.log("Response:", response);
        })
        .catch(({ message, response }) => {
          res = JSON.parse(response.request.response);
          if (res.msg) {
            $("#subscribeBody").prepend(
              `<div class="alert alert-danger alert-dismissible" role="alert"> <button type="button" class="close" data-dismiss="alert" aria-label="Close"><span aria-hidden="true">&times;</span></button>${res.msg}</div>`
            );
          }
        });
      event.preventDefault();
    });
  }
  formSubmit();




